<script setup>
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import SeedingResultPopup from '../components/SeedingResultPopup.vue'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
import {useStudyActivity} from '../composables/useStudyActivity'
const arcade=useArcade(),enabled=ref(false),loaded=ref(false),session=ref(null),answers=ref({}),busy=ref(false),error=ref(''),saving=ref(false),saveLabel=ref('서버에 자동 저장됩니다'),form=ref(null)
const resultPopup=ref(null),questionCount=ref(25)
const total=computed(()=>session.value?.questions.length??questionCount.value)
const subjects=ref([]),subject=ref('numpy-pandas'),type=ref('short'),choosing=ref(true)
const typeName=value=>value==='multiple'?'객관식':'주관식'
const subjectName=value=>subjects.value.find(s=>s.id===value)?.name??'기존 통합 세트'
const count=computed(()=>session.value?.questions.filter(q=>answers.value[q.id]?.trim()).length??0)
let timer,poll,pending=Promise.resolve(),disposed=false
function accept(data){session.value=data;answers.value={...(data?.answers??{})};if(data&&data.subject!=='legacy'){subject.value=data.subject;type.value=data.type}}
async function load(){try{const data=await api('/seeding');enabled.value=data.enabled;subjects.value=data.subjects;questionCount.value=data.questionCount;accept(data.session);loaded.value=true}catch(e){error.value=e.message}}
async function start(){if(busy.value)return;busy.value=true;error.value='';try{accept(await api('/seeding/start',{method:'POST',body:{subject:subject.value,type:type.value}}));choosing.value=false;saveLabel.value='서버에 자동 저장됩니다'}catch(e){error.value=e.message}finally{busy.value=false}}
function save(){
 clearTimeout(timer)
 pending=pending.catch(()=>{}).then(async()=>{
  const current=session.value;if(!enabled.value||!current||current.result)return
  const snapshot={...answers.value};if(JSON.stringify(snapshot)===JSON.stringify(current.answers))return
  saving.value=true
  try{const data=await api('/seeding/'+current.id+'/draft',{method:'POST',body:{answers:snapshot,revision:current.revision},keepalive:disposed});if(session.value?.id===current.id){current.revision=data.revision;current.answers=data.answers;saveLabel.value='자동 저장 완료'}return true}
  catch(e){error.value=e.message;saveLabel.value='저장 실패 · 다시 시도해 주세요';throw e}finally{saving.value=false}
 })
 return pending
}
watch(answers,()=>{clearTimeout(timer);if(!session.value?.result){saveLabel.value='저장 대기 중…';timer=setTimeout(()=>save().catch(()=>{}),900)}},{deep:true})
function resume(){if(session.value?.subject!=='legacy'){subject.value=session.value.subject;type.value=session.value.type}choosing.value=false}
async function choose(){try{await save();choosing.value=true}catch{}}
async function submit(){if(busy.value||count.value!==total.value)return;if(!form.value.reportValidity())return;busy.value=true;error.value='';try{await save();const data=await api('/seeding/'+session.value.id+'/submit',{method:'POST',body:{answers:answers.value,revision:session.value.revision}});accept(data);window.scrollTo({top:0,behavior:'instant'});resultPopup.value=data.result;await arcade.refresh();window.dispatchEvent(new Event('spokemon-points-refresh'))}catch(e){error.value=e.message}finally{busy.value=false}}
useStudyActivity(()=>enabled.value&&!choosing.value&&session.value&&!session.value.result?{kind:'seeding',sessionId:session.value.id}:null)
onMounted(()=>{load();poll=setInterval(async()=>{try{enabled.value=(await api('/seeding/settings',{background:true})).enabled}catch{}},15000)})
onUnmounted(()=>{disposed=true;clearTimeout(timer);clearInterval(poll);save().catch(()=>{})})
</script>
<template><section class="seeding-page">
 <header class="panel seed-banner"><span class="eyebrow">SPECIAL STUDY CHALLENGE</span><h1>✨ GT's seeding</h1><h2>열심히 해서 1시드를 노려보세요!!!!</h2><p>아 공부 안 하게? 안 하게? 안 하게? 안 하게? 안 하게?<br>4시드 가게? 4시드? 1시드 안 하게? 1시드 놓치게?</p><div class="seed-perks"><span>한 번에 25문제</span><span>완료마다 500P</span><span>공부시간 합산 · 누적 2시간 전설 도전</span></div></header>
 <p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="!loaded">문제를 준비하고 있어요…</p>
 <section v-else-if="!enabled" class="panel"><h2>지금은 준비 중이에요.</h2><p>관리자가 공개하면 다시 도전할 수 있어요. 풀이 기록과 보상은 유지됩니다.</p></section>
 <template v-else><section v-if="choosing" class="panel seed-start">
 <h2>과목과 문제 유형을 선택하세요</h2><p>각 자료를 별도 과목으로 나눴어요. 선택한 과목·유형에서 25문제를 한꺼번에 풀고 제출합니다.</p>
 <fieldset class="seed-subjects"><legend>과목</legend><button v-for="item in subjects" :key="item.id" type="button" :class="{selected:subject===item.id}" :aria-pressed="subject===item.id" :disabled="busy" @click="subject=item.id"><strong>{{item.name}}</strong><span>{{item.description}}</span><small>유형별 {{item.count}}문제</small></button></fieldset>
 <fieldset class="seed-types"><legend>문제 유형</legend><button v-for="item in ['multiple','short']" :key="item" type="button" :class="{selected:type===item}" :aria-pressed="type===item" :disabled="busy" @click="type=item">{{typeName(item)}} 버전</button></fieldset>
 <p>정답과 해설은 전체 제출 후 공개됩니다. 25문제 완료마다 500P를 받아요. 공부시간은 기존 누적 2시간 전설 보상 조건에 합산됩니다.</p>
 <div class="toolbar"><button :disabled="busy" @click="start">{{subjectName(subject)}} · {{typeName(type)}} 25문제 시작</button><button v-if="session" class="light" :disabled="busy" @click="resume">{{session.result?'최근 결과 보기':'이어서 풀기'}} · {{subjectName(session.subject)}} / {{typeName(session.type)}}</button></div>
 </section>
 <template v-else-if="session"><div class="seed-session-bar"><h2>{{subjectName(session.subject)}} <small>{{typeName(session.type)}} 버전</small></h2><button class="light" :disabled="busy||saving" @click="choose">과목·유형 선택</button></div><section v-if="session.result" class="panel seed-result" role="status"><h2>{{total}}문제 도전 완료! +500P</h2><p class="seed-score">{{session.result.score}}점 <small>/ 100점</small></p><p>{{session.result.correct}} / {{total}}문제 정답 · {{session.result.outcome==='retake'?'재시험 당첨!':'통과했어요! ♥'}}</p><button class="light" @click="resultPopup=session.result">점수 팝업 다시 보기</button><p>아래에서 제출한 답안과 정답·해설을 함께 확인하세요.</p><button :disabled="busy" @click="start">같은 과목·유형으로 새로운 25문제</button><RouterLink to="/legendary" class="button light">전설 도감 확인</RouterLink></section>
 <form ref="form" @submit.prevent="submit"><div class="seed-progress"><b>{{session.result?'제출 완료':count+' / '+total+'문제 작성'}}</b><small role="status">{{session.result?'500P 지급 완료':saving?'저장 중…':saveLabel}}</small><button v-if="!session.result" type="button" class="light" :disabled="busy||saving" @click="save().catch(()=>{})">지금 저장</button></div>
 <div class="seed-questions"><article v-for="(q,index) in session.questions" :key="q.id" class="panel seed-question" :class="session.result?{right:session.result.items[index].correct,wrong:!session.result.items[index].correct}:{}">
 <div class="seed-prompt"><h2><span>Q{{String(index+1).padStart(2,'0')}}</span> {{q.prompt}}</h2><pre v-if="q.code"><code>{{q.code}}</code></pre></div>
 <fieldset v-if="q.type==='multiple'" class="seed-answer seed-options" :disabled="busy||!!session.result"><legend>{{session.result?'내가 제출한 선택지':'정답을 선택하세요'}}</legend><label v-for="(option,i) in q.options" :key="option.id" :class="{selected:answers[q.id]===option.id,correct:session.result&&q.correctOptionId===option.id}"><input v-model="answers[q.id]" type="radio" :name="q.id" :value="option.id" required><span>{{i+1}}. {{option.text}}</span></label></fieldset>
 <label v-else class="seed-answer seed-short" :for="q.id">{{session.result?'내가 제출한 답':'답안'}}<input :id="q.id" v-model="answers[q.id]" :disabled="busy||!!session.result" required maxlength="200" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="답안을 입력하세요"></label>
 <div class="seed-feedback"><template v-if="session.result"><b>{{session.result.items[index].correct?'✓ 정답':'다시 기억해 봐요'}}</b><p>정답: {{q.correctAnswer}}</p><p>{{q.explanation}}</p></template></div>
 </article></div>
 <section v-if="!session.result" class="panel seed-submit"><p>{{count===total?'모든 답안을 작성했어요! 제출하면 정답·해설과 500P를 받습니다.':'아직 '+(total-count)+'문제가 남았어요. 답안을 모두 작성해 주세요.'}}</p><small>영문 대소문자·공백은 무시합니다. 여러 빈칸은 문제 안내에 따라 쉼표로 구분하세요.</small><button :disabled="busy||count!==total">{{busy?'제출 중…':total+'문제 한꺼번에 제출 · 500P 받기'}}</button></section></form>
 </template></template>
</section><SeedingResultPopup :result="resultPopup" @close="resultPopup=null" @retry="resultPopup=null;start()"/></template>
<style scoped>
.seeding-page{width:100%;min-width:0;max-width:1200px;margin:auto}.seeding-page>header.seed-banner{display:block;width:100%;box-sizing:border-box}.seed-banner{background:linear-gradient(135deg,var(--rpg-soft),var(--rpg-bright));border:3px solid var(--rpg-edge);overflow:hidden}.seed-banner h1{font-size:clamp(25px,4vw,38px);margin:10px 0}.seed-banner h2{font-size:clamp(17px,2.6vw,23px)}.seed-banner p{line-height:1.9}.seed-perks{display:flex;flex-wrap:wrap;gap:9px}.seed-perks span{padding:7px 10px;border:1px solid var(--rpg-mid);background:var(--rpg-paper);font-size:12px}.seed-progress{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:14px 0}.seed-progress small{margin-right:auto}.seed-questions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;align-items:stretch}.seed-question{min-width:0;margin:0!important;padding:20px!important;box-sizing:border-box;display:grid;grid-template-rows:subgrid;grid-row:span 3;row-gap:12px}.seed-prompt{min-width:0}.seed-prompt pre{margin-bottom:0}.seed-question h2{font-size:15px;line-height:1.8;overflow-wrap:anywhere;margin:0 0 14px}.seed-question h2 span{color:var(--rpg-edge)}.seed-question pre{max-width:100%;overflow:auto;box-sizing:border-box;padding:12px;background:#182539;color:#f0f5ff;border-radius:5px;font:12px/1.7 monospace;white-space:pre;tab-size:2}.seed-question .seed-short{display:grid;gap:8px;font-size:12px}.seed-question .seed-short input{min-width:0;width:100%;box-sizing:border-box;margin:0;font-size:14px}.seed-feedback{line-height:1.8;font-size:12px;overflow-wrap:anywhere;padding-top:0}.seed-question.right{border-color:#337c55}.seed-question.wrong{border-color:#bd7440}.seed-submit{margin-top:20px;display:grid;gap:14px}.seed-submit button{justify-self:start;max-width:100%;white-space:normal}.seed-result{margin-bottom:20px}.seed-score{font-size:36px!important;font-weight:bold;margin:15px 0}.seed-score small{font-size:14px}.seed-start p{line-height:1.9}.seed-subjects,.seed-types{border:0;padding:0;margin:18px 0;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;min-width:0}.seed-subjects legend,.seed-types legend{font-weight:bold;margin-bottom:10px}.seed-subjects button{display:flex;flex-direction:column;align-items:flex-start;gap:9px;text-align:left;min-width:0;white-space:normal;margin:0;padding:16px!important;height:auto!important;min-height:120px}.seed-subjects button span{font-size:12px;line-height:1.7}.seed-subjects button small{font-size:11px}.seed-subjects .selected,.seed-types .selected{outline:3px solid var(--rpg-mid);outline-offset:2px}.seed-types button{white-space:normal;margin:0}.seed-start .toolbar button{white-space:normal;max-width:100%}.seed-session-bar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:18px 0}.seed-session-bar h2{font-size:19px}.seed-session-bar small{font-size:12px}.seed-question .seed-options{border:0;padding:0;margin:0;min-width:0;display:grid;gap:8px;align-content:start}.seed-options legend{font-size:12px;margin-bottom:8px}.seed-options label{display:flex;gap:9px;align-items:center;min-width:0;padding:10px;border:1px solid var(--rpg-mid);background:var(--rpg-soft);cursor:pointer;font-size:13px;line-height:1.7;overflow-wrap:anywhere}.seed-options label.selected{border:2px solid var(--rpg-edge);padding:9px;background:var(--rpg-bright)}.seed-options label.correct{outline:2px solid #337c55}.seed-options input[type=radio]{width:17px;height:17px;min-width:17px;flex:none;margin:0;padding:0;accent-color:var(--rpg-edge)}.seed-options span{min-width:0}.seed-answer{min-width:0}h1,h2,p{overflow-wrap:anywhere}@media(max-width:700px){.seed-subjects{grid-template-columns:minmax(0,1fr)}.seed-question{grid-row:span 3}.seed-questions{grid-template-columns:minmax(0,1fr)}.seed-question{padding:15px!important}.seed-perks span{font-size:10px}.seed-progress{font-size:12px}.seed-banner{padding:20px!important}}
</style>
